import{_ as t,o as i,c as n,a3 as a}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Deleting entries","description":"Delete individual entries and multiple entries at once.","frontmatter":{"title":"Deleting entries","description":"Delete individual entries and multiple entries at once."},"headers":[],"relativePath":"en/grids/eintraege-loeschen.md","filePath":"en/grids/eintraege-loeschen.md","lastUpdated":1788108473000}'),r={name:"en/grids/eintraege-loeschen.md"};function l(s,e,o,d,h,c){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="deleting-entries" tabindex="-1">Deleting entries <a class="header-anchor" href="#deleting-entries" aria-label="Permalink to &quot;Deleting entries&quot;">​</a></h1><h2 id="deleting-a-single-entry" tabindex="-1">Deleting a single entry <a class="header-anchor" href="#deleting-a-single-entry" aria-label="Permalink to &quot;Deleting a single entry&quot;">​</a></h2><p>Via the row menu. ApptiveGrid asks for confirmation: <em>Are you sure?</em></p><h2 id="deleting-multiple-entries" tabindex="-1">Deleting multiple entries <a class="header-anchor" href="#deleting-multiple-entries" aria-label="Permalink to &quot;Deleting multiple entries&quot;">​</a></h2><ol><li>Select the entries in the table.</li><li>Click <strong>Delete {number}</strong>.</li><li>Confirm in the dialog <em>Delete {number} entries?</em> with <strong>Delete</strong>.</li></ol><div class="danger custom-block"><p class="custom-block-title">Deletion is final</p><p>Deleted entries can&#39;t be restored within the app. The <a href="/en/grids/versionsverlauf">version history</a> shows changes to field values, but doesn&#39;t bring back a deleted entry.</p><p>For larger deletion actions, take a <a href="/en/grids/csv-export">CSV export</a> first.</p></div><h2 id="when-deletion-doesn-t-work" tabindex="-1">When deletion doesn&#39;t work <a class="header-anchor" href="#when-deletion-doesn-t-work" aria-label="Permalink to &quot;When deletion doesn&#39;t work&quot;">​</a></h2><blockquote><p><em>Delete not possible. The entry is still referenced elsewhere.</em></p></blockquote><p>Or, naming the referencing entry:</p><blockquote><p><em>Delete not possible. The entry is still referenced by {entry}.</em></p></blockquote><p>The entry is connected to another entry via a <a href="/en/grids/verknuepfungen">link</a>. Remove these references first.</p><div class="tip custom-block"><p class="custom-block-title">If the message names the entry, go straight there</p><p>In the second variant, it states which entry holds the reference — that saves you the search.</p><p>If it doesn&#39;t, switch to the referencing Grid and filter on the link column. For <em>Link record</em>, a filter on the relevant value takes you directly to all affected rows.</p></div><p>This safeguard is intentional — it prevents references pointing into thin air.</p><h2 id="be-careful-with-filtered-views" tabindex="-1">Be careful with filtered views <a class="header-anchor" href="#be-careful-with-filtered-views" aria-label="Permalink to &quot;Be careful with filtered views&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">You&#39;re deleting real entries, not rows of a view</p><p>A view only shows a subset. But deletion always acts on the <strong>Grid</strong> — afterward, the entry is gone from every view.</p><p>Before a bulk deletion, make sure the filter matches exactly what you mean. A look at the count in the delete dialog helps: if it&#39;s unexpectedly high, the selection is off.</p></div><h2 id="deletion-and-flows" tabindex="-1">Deletion and flows <a class="header-anchor" href="#deletion-and-flows" aria-label="Permalink to &quot;Deletion and flows&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">There&#39;s no trigger for deleted entries</p><p>The available <a href="/en/flows/trigger">triggers</a> react to new and changed entries, not to deletions. So a flow can&#39;t react to a deletion.</p><p>If something should happen on &quot;removal,&quot; use a status field instead: set the entry to <code>Canceled</code> instead of deleting it, and have the flow react to that change.</p></div><h2 id="alternatives-to-deleting" tabindex="-1">Alternatives to deleting <a class="header-anchor" href="#alternatives-to-deleting" aria-label="Permalink to &quot;Alternatives to deleting&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Hiding is often better</p><table tabindex="0"><thead><tr><th>Instead of deleting …</th><th>Approach</th></tr></thead><tbody><tr><td>Old entries clutter the overview</td><td>Filter the view, e.g. to the last 12 months</td></tr><tr><td>Entry is finished</td><td>Status field set to <code>Done</code>, view filtered on it</td></tr><tr><td>Entry was a mistake</td><td>Deleting is the right call here</td></tr><tr><td>Data must be retained</td><td>Don&#39;t delete — filter</td></tr></tbody></table><p>Filtered entries still count against the <a href="/en/grids/eintraege#limits">plan-dependent number of entries per Grid</a>. If that matters, deleting is the only option — but with an export beforehand.</p></div><h2 id="deleting-the-grid-instead-of-entries" tabindex="-1">Deleting the Grid instead of entries <a class="header-anchor" href="#deleting-the-grid-instead-of-entries" aria-label="Permalink to &quot;Deleting the Grid instead of entries&quot;">​</a></h2><p>If the entire dataset should go, deleting the Grid is the more direct route. Check beforehand whether views, forms, flows, or <a href="/en/seiten/was-sind-seiten">pages</a> access it.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/eintraege">Creating and editing entries</a></li><li><a href="/en/grids/versionsverlauf">Version history</a></li><li><a href="/en/grids/csv-export">CSV Export</a></li></ul>',23)])])}const p=t(r,[["render",l]]);export{g as __pageData,p as default};
